#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;
const int N = 1e5 + 10;

int f[N][10];
string s;
int n;

int dp(int pos, int last, bool is_limit, bool is_num) {
    if (pos == n) {
        return is_num ? 1 : 0;
    }
    if (!is_limit && is_num && f[pos][last] != -1) {
        return f[pos][last];
    }

    int res = 0;
    // 跳过当前位
    if (!is_num) {
        res = dp(pos + 1, last, false, false);
    }

    int up = is_limit ? s[pos] - '0' : 9;
    int start = is_num ? 0 : 1;
    for (int d = start; d <= up; ++d) {
        if (d != last) { // 满足流畅数条件
            res = (res + dp(pos + 1, d, is_limit && (d == up), true)) % MOD;
        }
    }

    if (!is_limit && is_num) {
        f[pos][last] = res;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    n = s.size();
    memset(f, -1, sizeof(f));
    int ans = dp(0, 0, true, false);
    cout << ans << '\n';
    return 0;
}
